+const IGNORED = new Set(['.git', '.stdd', 'node_modules', 'vendor', 'dist', 'build', 'coverage', 'draw_assets']);
+const EXTENSIONS = new Set(['.js', '.jsx', '.ts', '.tsx', '.mjs', '.cjs']);
+const result = {
+  contract_version: '1', status: 'passed',
